(()=>{
 const stages=[['THE QUESTION','Give curiosity a direction.','Start with something you want to understand. Make the question specific enough to guide your next move.','Find your starting point','#lesson/0','?'],['THE SOURCES','Bring different perspectives together.','Gather sources you can trace. Record their context, methods, and the reason each belongs in your study.','Build your source library','#research','○'],['THE EVIDENCE','Connections deserve a closer look.','Compare what the sources actually show. Keep exact passages separate from your own interpretation.','Explore evidence tools','#toolkit','⌁'],['THE ARGUMENT','Make every claim accountable.','Explain your reasoning. Show which evidence supports it, where it is limited, and what still needs to be understood.','Shape your proposal','#notebook/draft','→']];
 const moving=()=>document.documentElement.dataset.motion!=='off'&&!matchMedia('(prefers-reduced-motion:reduce)').matches;
 let panelAnimation,focused=false;
 function stage(index,focus=false){const instrument=document.querySelector('.atelier-instrument');if(!instrument)return;const data=stages[index];instrument.dataset.stage=index;document.querySelectorAll('[data-atelier-stage]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===index));b.tabIndex=i===index?0:-1;if(focus&&i===index)b.focus()});const panel=document.querySelector('#atelier-panel');panel.setAttribute('aria-labelledby','atelier-tab-'+index);document.querySelector('#atelier-stage-label').textContent='0'+(index+1)+' / '+data[0];document.querySelector('#atelier-stage-title').textContent=data[1];document.querySelector('#atelier-stage-copy').textContent=data[2];const link=document.querySelector('#atelier-stage-link');link.href=data[4];link.innerHTML=data[3]+' <span aria-hidden="true">↗</span>';instrument.querySelector('.atelier-core text').textContent=data[5];panelAnimation?.cancel();if(moving())panelAnimation=panel.animate([{opacity:.3,transform:'translateY(9px)'},{opacity:1,transform:'none'}],{duration:350,easing:'ease-out'})}
 document.addEventListener('click',ev=>{const b=ev.target.closest('[data-atelier-stage]');if(b)stage(Number(b.dataset.atelierStage))});
 document.addEventListener('keydown',ev=>{const b=ev.target.closest('[data-atelier-stage]');if(!b||!['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'].includes(ev.key))return;ev.preventDefault();const i=Number(b.dataset.atelierStage);stage(ev.key==='Home'?0:ev.key==='End'?3:(i+(['ArrowRight','ArrowDown'].includes(ev.key)?1:3))%4,true)});
 function desk(){const content=document.querySelector('.research-content'),container=document.querySelector('.research-desk');if(!content||!container||content.querySelector('.atelier-desk-tools'))return;container.classList.toggle('atelier-focused',focused);const tools=document.createElement('div');tools.className='atelier-desk-tools';const location=document.createElement('span');location.className='atelier-desk-location';const dot=document.createElement('i');dot.setAttribute('aria-hidden','true');location.append(dot,document.createTextNode('RESEARCH DESK / '+(document.querySelector('.research-tabs [aria-current]')?.textContent||'Workspace').toUpperCase()));const button=document.createElement('button');button.type='button';button.className='atelier-focus';button.textContent=focused?'Show project navigation':'Focus this room';button.setAttribute('aria-pressed',String(focused));button.addEventListener('click',()=>{focused=!focused;container.classList.toggle('atelier-focused',focused);button.textContent=focused?'Show project navigation':'Focus this room';button.setAttribute('aria-pressed',String(focused))});tools.append(location,button);content.prepend(tools);
  const editor=content.querySelector('#project-proposal');if(editor){const outline=document.createElement('details');outline.className='atelier-outline';const summary=document.createElement('summary');summary.textContent='Document outline';const nav=document.createElement('nav');nav.setAttribute('aria-label','Proposal sections');outline.append(summary,nav);editor.closest('.proposal-editor').after(outline);let timer;const update=()=>{nav.replaceChildren();const matches=[...editor.value.matchAll(/^#{1,3}\s+(.+)$/gm)].slice(0,30);if(!matches.length){const hint=document.createElement('p');hint.textContent='Start a section with # followed by a heading. Your outline will appear here as you write.';nav.append(hint)}matches.forEach(match=>{const b=document.createElement('button');b.type='button';b.textContent=match[1];b.addEventListener('click',()=>{editor.focus();editor.setSelectionRange(match.index,match.index+match[0].length);editor.scrollIntoView({block:'center',behavior:moving()?'smooth':'instant'})});nav.append(b)})};editor.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(update,250)});update()}
 }
 const descriptions={research:'Build your source library, read closely, and carry evidence into an accountable argument.',academy:'Move through nine lessons with worked examples, your own writing, and knowledge checks.',journey:'See where you are in the process and choose the next milestone your study needs.',toolkit:'Find editable instruments for searching, comparing evidence, planning methods, and reviewing your proposal.',notebook:'Keep unfinished ideas and working drafts within reach.',seminars:'Give one research task a focused session with a timed agenda and a tangible next step.'};
 const directory=document.querySelector('#space-navigator'),grid=directory?.querySelector('.space-grid');if(grid){const preview=document.createElement('div');preview.className='atelier-directory-preview';preview.setAttribute('aria-hidden','true');const number=document.createElement('span'),title=document.createElement('strong'),copy=document.createElement('p');number.textContent='YOUR NEXT MOVE';title.textContent='A space for every part of the process.';copy.textContent='Explore a destination to see what you can do there.';preview.append(number,title,copy);grid.before(preview);const update=ev=>{const link=ev.target.closest('.space-grid>a');if(!link)return;const destination=link.hash.slice(1).split('/')[0];title.textContent=link.querySelector('h3')?.textContent||destination;copy.textContent=descriptions[destination]||'Shape your draft, review your progress, and keep your next step in view.'};grid.addEventListener('pointerover',update);grid.addEventListener('focusin',update)}
 let visibility;function watchStudy(){visibility?.disconnect();const instrument=document.querySelector('.atelier-instrument');if(!instrument)return;visibility=new IntersectionObserver(entries=>entries.forEach(entry=>entry.target.dataset.visible=String(entry.isIntersecting)),{threshold:.1});visibility.observe(instrument)}
 addEventListener('rei:research-render',desk);addEventListener('rrh:route',()=>{panelAnimation?.cancel();watchStudy()});addEventListener('rrh:motion',()=>{if(!moving())panelAnimation?.cancel()});desk();watchStudy();
})();
